import itertools,json
rows=[{'subject':'x','answer':i%4} for i in range(5)]
r={}
for n in [0,1,2,5,6,-1]:
 fewshots=0; selected=[]
 for pq in rows:
  if fewshots==n: break
  if pq['subject']!='x': continue
  selected.append(pq)
 r[n]=len(selected)
checks=0
for p in itertools.permutations(range(4)):
 for a in range(4):
  assert p[p.index(a)]==a
  checks+=1
print(json.dumps({'requested_to_included':r,'shuffle_label_checks':checks}))

